import{_ as t,a0 as l,w as r,s as o,I as n,x as a,a1 as p,A as i,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"在 Linux 上使用開源軟件創建 SDN | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上使用開源軟件創建 SDN | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上使用開源軟件創建 SDN | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上使用開源軟件創建 SDN | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20200417 Create a SDN on Linux with open source","title":"在 Linux 上使用開源軟件創建 SDN","tag":"202005","desc":""},"relativePath":"202005/20200417 Create a SDN on Linux with open source.md","filePath":"[post].md"}'),g={name:"202005/20200417 Create a SDN on Linux with open source.md"};function u(h,s,c,f,k,b){const e=l("Link");return r(),o("div",null,[s[26]||(s[26]=n("h1",{id:"在-linux-上使用開源軟件創建-sdn",tabindex:"-1"},[a("在 Linux 上使用開源軟件創建 SDN "),n("a",{class:"header-anchor",href:"#在-linux-上使用開源軟件創建-sdn","aria-label":"Permalink to “在 Linux 上使用開源軟件創建 SDN”"},"​")],-1)),s[27]||(s[27]=n("blockquote",null,[n("p",null,"使用開源路由協議棧 Quagga，使你的 Linux 系統成為一台路由器。")],-1)),s[28]||(s[28]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202005/09/093541rqx3zr5dxn3yvnq6.jpg",alt:""})],-1)),n("p",null,[s[1]||(s[1]=a("網絡路由協議分為兩大類：內部網關協議和外部網關協議。路由器使用內部網關協議在單個自治系統內共享信息。如果你用的是 Linux，則可以通過開源（GPLv2）路由協議棧 ",-1)),p(e,{href:"https://www.quagga.net/"},{default:i(()=>[...s[0]||(s[0]=[a("Quagga",-1)])]),_:1}),s[2]||(s[2]=a(" 使其表現得像一台路由器。",-1))]),s[29]||(s[29]=n("h3",{id:"quagga-是什麼",tabindex:"-1"},[a("Quagga 是什麼？ "),n("a",{class:"header-anchor",href:"#quagga-是什麼","aria-label":"Permalink to “Quagga 是什麼？”"},"​")],-1)),n("p",null,[s[5]||(s[5]=a("Quagga 是一個",-1)),p(e,{href:"https://en.wikipedia.org/wiki/Quagga_(software)"},{default:i(()=>[...s[3]||(s[3]=[a("路由軟件包",-1)])]),_:1}),s[6]||(s[6]=a("，並且是 ",-1)),p(e,{href:"https://www.gnu.org/software/zebra/"},{default:i(()=>[...s[4]||(s[4]=[a("GNU Zebra",-1)])]),_:1}),s[7]||(s[7]=a(" 的一個分支。它為類 Unix 平台提供了所有主流路由協議的實現，例如開放最短路徑優先（OSPF），路由信息協議（RIP），邊界網關協議（BGP）和中間系統到中間系統協議（IS-IS）。",-1))]),s[30]||(s[30]=n("p",null,"儘管 Quagga 實現了 IPv4 和 IPv6 的路由協議，但它並不是一個完整的路由器。一個真正的路由器不僅實現了所有路由協議，而且還有轉發網絡流量的能力。 Quagga 僅僅實現了路由協議棧，而轉發網絡流量的工作由 Linux 內核處理。",-1)),s[31]||(s[31]=n("h3",{id:"架構",tabindex:"-1"},[a("架構 "),n("a",{class:"header-anchor",href:"#架構","aria-label":"Permalink to “架構”"},"​")],-1)),n("p",null,[s[9]||(s[9]=a("Quagga 通過特定協議的守護程序實現不同的路由協議。守護程序名稱與路由協議相同，加了字母“d”作為後綴。Zebra 是核心，也是與協議無關的守護進程，它為內核提供了一個",-1)),p(e,{href:"https://en.wikipedia.org/wiki/Abstraction_layer"},{default:i(()=>[...s[8]||(s[8]=[a("抽象層",-1)])]),_:1}),s[10]||(s[10]=a("，並通過 TCP 套接字向 Quagga 客户端提供 Zserv API。每個特定協議的守護程序負責運行相關的協議，並基於交換的信息來建立路由表。",-1))]),s[32]||(s[32]=d(`<p><img src="https://opensource.com/sites/default/files/uploads/quagga_arch.png" alt="Quagga architecture" title="Quagga architecture"></p><h3 id="環境" tabindex="-1">環境 <a class="header-anchor" href="#環境" aria-label="Permalink to “環境”">​</a></h3><p>本教程通過 Quagga 實現的 OSPF 協議來配置動態路由。該環境包括兩個名為 Alpha 和 Beta 的 CentOS 7.7 主機。兩台主機共享訪問 <strong>192.168.122.0/24</strong> 網絡。</p><p><strong>主機 Alpha：</strong></p><p>IP：192.168.122.100/24 網關：192.168.122.1</p><p><strong>主機 Beta：</strong></p><p>IP：192.168.122.50/24 網關：192.168.122.1</p><h3 id="安裝軟件包" tabindex="-1">安裝軟件包 <a class="header-anchor" href="#安裝軟件包" aria-label="Permalink to “安裝軟件包”">​</a></h3><p>首先，在兩台主機上安裝 Quagga 軟件包。它存在於 CentOS 基礎倉庫中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>yum install quagga -y</span></span></code></pre></div><h3 id="啓用-ip-轉發" tabindex="-1">啓用 IP 轉發 <a class="header-anchor" href="#啓用-ip-轉發" aria-label="Permalink to “啓用 IP 轉發”">​</a></h3><p>接下來，在兩台主機上啓用 IP 轉發，因為它將由 Linux 內核來執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sysctl -w net.ipv4.ip_forward = 1</span></span>
<span class="line"><span>sysctl -p</span></span></code></pre></div><h3 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h3><p>現在，進入 <code>/etc/quagga</code> 目錄併為你的設置創建配置文件。你需要三個文件：</p><ul><li><code>zebra.conf</code>：Quagga 守護程序的配置文件，你可以在其中定義接口及其 IP 地址和 IP 轉發</li><li><code>ospfd.conf</code>：協議配置文件，你可以在其中定義將通過 OSPF 協議提供的網絡</li><li><code>daemons</code>：你將在其中指定需要運行的相關的協議守護程序</li></ul><p>在主機 Alpha 上，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> [root@alpha]# cat /etc/quagga/zebra.conf</span></span>
<span class="line"><span>interface eth0</span></span>
<span class="line"><span> ip address 192.168.122.100/24</span></span>
<span class="line"><span> ipv6 nd suppress-ra</span></span>
<span class="line"><span>interface eth1</span></span>
<span class="line"><span> ip address 10.12.13.1/24</span></span>
<span class="line"><span> ipv6 nd suppress-ra</span></span>
<span class="line"><span>interface lo</span></span>
<span class="line"><span>ip forwarding</span></span>
<span class="line"><span>line vty</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[root@alpha]# cat /etc/quagga/ospfd.conf</span></span>
<span class="line"><span>interface eth0</span></span>
<span class="line"><span>interface eth1</span></span>
<span class="line"><span>interface lo</span></span>
<span class="line"><span>router ospf</span></span>
<span class="line"><span> network 192.168.122.0/24 area 0.0.0.0</span></span>
<span class="line"><span> network 10.12.13.0/24 area 0.0.0.0</span></span>
<span class="line"><span>line vty</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[root@alphaa ~]# cat /etc/quagga/daemons</span></span>
<span class="line"><span>zebra=yes</span></span>
<span class="line"><span>ospfd=yes</span></span></code></pre></div><p>在主機 Beta 上，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@beta quagga]# cat zebra.conf</span></span>
<span class="line"><span>interface eth0</span></span>
<span class="line"><span> ip address 192.168.122.50/24</span></span>
<span class="line"><span> ipv6 nd suppress-ra</span></span>
<span class="line"><span>interface eth1</span></span>
<span class="line"><span> ip address 10.10.10.1/24</span></span>
<span class="line"><span> ipv6 nd suppress-ra</span></span>
<span class="line"><span>interface lo</span></span>
<span class="line"><span>ip forwarding</span></span>
<span class="line"><span>line vty</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[root@beta quagga]# cat ospfd.conf</span></span>
<span class="line"><span>interface eth0</span></span>
<span class="line"><span>interface eth1</span></span>
<span class="line"><span>interface lo</span></span>
<span class="line"><span>router ospf</span></span>
<span class="line"><span> network 192.168.122.0/24 area 0.0.0.0</span></span>
<span class="line"><span> network 10.10.10.0/24 area 0.0.0.0</span></span>
<span class="line"><span>line vty</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[root@beta ~]# cat /etc/quagga/daemons</span></span>
<span class="line"><span>zebra=yes</span></span>
<span class="line"><span>ospfd=yes</span></span></code></pre></div><h3 id="配置防火牆" tabindex="-1">配置防火牆 <a class="header-anchor" href="#配置防火牆" aria-label="Permalink to “配置防火牆”">​</a></h3><p>要使用 OSPF 協議，必須允許它通過防火牆：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --add-protocol=ospf –permanent</span></span>
<span class="line"><span></span></span>
<span class="line"><span>firewall-cmd –reload</span></span></code></pre></div><p>現在，啓動 <code>zebra</code> 和 <code>ospfd</code> 守護程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl start zebra</span></span>
<span class="line"><span># systemctl start ospfd</span></span></code></pre></div><p>用下面命令在兩個主機上查看路由表:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@alpha ~]# ip route show  </span></span>
<span class="line"><span>default via 192.168.122.1 dev eth0 proto static metric 100</span></span>
<span class="line"><span>10.10.10.0/24 via 192.168.122.50 dev eth0 proto zebra metric 20</span></span>
<span class="line"><span>10.12.13.0/24 dev eth1 proto kernel scope link src 10.12.13.1</span></span>
<span class="line"><span>192.168.122.0/24 dev eth0 proto kernel scope link src 192.168.122.100 metric 100</span></span></code></pre></div><p>你可以看到 Alpha 上的路由表包含通過 <strong>192.168.122.50</strong> 到達 <strong>10.10.10.0/24</strong> 的路由項，它是通過協議 zebra 獲取的。同樣，在主機 Beta 上，該表包含通過 <strong>192.168.122.100</strong> 到達網絡 <strong>10.12.13.0/24</strong> 的路由項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@beta ~]# ip route show</span></span>
<span class="line"><span>default via 192.168.122.1 dev eth0 proto static metric 100</span></span>
<span class="line"><span>10.10.10.0/24 dev eth1 proto kernel scope link src 10.10.10.1</span></span>
<span class="line"><span>10.12.13.0/24 via 192.168.122.100 dev eth0 proto zebra metric 20</span></span>
<span class="line"><span>192.168.122.0/24 dev eth0 proto kernel scope link src 192.168.122.50 metric 100</span></span></code></pre></div><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>如你所見，環境和配置相對簡單。要增加複雜性，你可以向路由器添加更多網絡接口，以為更多網絡提供路由。你也可以使用相同的方法來實現 BGP 和 RIP 協議。</p><hr>`,32)),n("p",null,[s[12]||(s[12]=a("via: ",-1)),p(e,{href:"https://opensource.com/article/20/4/quagga-linux"},{default:i(()=>[...s[11]||(s[11]=[a("https://opensource.com/article/20/4/quagga-linux",-1)])]),_:1})]),n("p",null,[s[17]||(s[17]=a("作者：",-1)),p(e,{href:"https://opensource.com/users/noisybotnet"},{default:i(()=>[...s[13]||(s[13]=[a("M Umer",-1)])]),_:1}),s[18]||(s[18]=a(" 選題：",-1)),p(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[14]||(s[14]=[a("lujun9972",-1)])]),_:1}),s[19]||(s[19]=a(" 譯者：",-1)),p(e,{href:"https://github.com/messon007"},{default:i(()=>[...s[15]||(s[15]=[a("messon007",-1)])]),_:1}),s[20]||(s[20]=a(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[16]||(s[16]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[23]||(s[23]=a("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[21]||(s[21]=[a("LCTT",-1)])]),_:1}),s[24]||(s[24]=a(" 原創編譯，",-1)),p(e,{href:"https://linux.cn/"},{default:i(()=>[...s[22]||(s[22]=[a("Linux中國",-1)])]),_:1}),s[25]||(s[25]=a(" 榮譽推出",-1))])])}const y=t(g,[["render",u]]);export{v as __pageData,y as default};
